keyframes.cssText:
@keyframes fadeInUp { 
  0% { opacity: 0; transform: translateY(30px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes floatY { 
  0% { transform: translateY(0px); }
  50% { transform: translateY(-15px); }
  100% { transform: translateY(0px); }
}

@keyframes scaleIn { 
  0% { opacity: 0; transform: scale(0.94); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes sway3d { 
  0% { transform: perspective(900px) rotateY(-4deg) rotateX(1.5deg); }
  50% { transform: perspective(900px) rotateY(4deg) rotateX(-1.5deg); }
  100% { transform: perspective(900px) rotateY(-4deg) rotateX(1.5deg); }
}

@keyframes craneGlide { 
  0% { transform: translateY(0px) rotate(0deg); }
  30% { transform: translateY(-14px) rotate(-2.5deg); }
  60% { transform: translateY(6px) rotate(1.5deg); }
  100% { transform: translateY(0px) rotate(0deg); }
}

@keyframes cloudDrift { 
  0% { transform: translate(0px); }
  50% { transform: translate(26px); }
  100% { transform: translate(0px); }
}

@keyframes petalFall { 
  0% { opacity: 0; transform: translateY(-8vh) translate(0px) rotate(0deg); }
  8% { opacity: 0.9; }
  85% { opacity: 0.8; }
  100% { opacity: 0; transform: translateY(96vh) translate(-6vw) rotate(320deg); }
}

@keyframes lanternSwing { 
  0% { transform: rotate(-4deg); }
  50% { transform: rotate(4deg); }
  100% { transform: rotate(-4deg); }
}

@keyframes tourRingPulse { 
  0%, 100% { box-shadow: 0 0 0 3px #fff,0 0 0 6px var(--color-fnb-orange),0 0 20px 2px color-mix(in srgb,var(--color-fnb-red) 45%,transparent); }
  50% { box-shadow: 0 0 0 3px #fff,0 0 0 8px var(--color-fnb-orange),0 0 32px 8px color-mix(in srgb,var(--color-fnb-red) 55%,transparent); }
}

@keyframes tourAvatarPulse { 
  0% { opacity: 0.9; transform: scale(0.85); }
  100% { opacity: 0; transform: scale(1.7); }
}

@keyframes bounce { 
  0%, 100% { animation-timing-function: cubic-bezier(0.8, 0, 1, 1); transform: translateY(-25%); }
  50% { animation-timing-function: cubic-bezier(0, 0, 0.2, 1); transform: none; }
}
